create unique index if not exists uq_teacher_unavailability_active_slot on teacher_unavailability(institution_code,teacher_id,weekday,period) where active;
create or replace function preserve_manual_schedule_v1(p_preserve boolean default true) returns integer language plpgsql security definer set search_path=public as $$declare n int;begin perform open_permission_context('schedule.edit');if p_preserve then update teacher_schedule set locked=true,updated_at=now() where institution_code=current_tenant_code() and active and source_kind in('manual','voice_manual') and not locked;get diagnostics n=row_count;else n:=0;end if;return n;end$$;